            $fetched_enable_upcoming,
            $fetched_enable_1min,
            $fetched_enable_start,
            $fetched_enable_end,
            $fetched_enable_snoozed,
            $fetched_enable_ai,
            $fetched_enable_raid_snooze,
            $fetched_raid_window,
            $fetched_enable_raid_msg,
            $fetched_raid_msg
