    $soundFiles = [];
    if (is_dir($soundPath)) {
        $soundFiles = array_values(array_diff(scandir($soundPath) ?: [], ['.', '..']));
    }

    $default_chat_alerts = modules_default_chat_alerts();
    $chat_alerts = [];
