        $stmt->close();
    }
    foreach ($default_chat_alerts as $type => $default_message) {
        if (!isset($chat_alerts[$type]) || trim((string) $chat_alerts[$type]) === '') {
            $chat_alerts[$type] = $default_message;
        }
    }

    $ignored_games = [];
    $stmt = $db->prepare("SELECT game_name FROM game_deaths_settings");
