        while ($row = $commandOptionsResult->fetch_assoc()) {
            $cmd = ltrim(strtolower(trim((string) ($row['command'] ?? ''))), '!');
            if ($cmd !== '') {
                $availableBlockFirstMessageCommands[$cmd] = $cmd;
            }
        }
        $commandOptionsResult->free();
